<div id="alertNote" class="fixed bottom-4 right-4 max-w-xs bg-coffee text-white rounded-2xl shadow-xl p-4 hidden" role="status"></div><script>
const API=<?= json_encode(BASE_URL.'/api/orders.php') ?>,csrf=<?= json_encode(csrf_token()) ?>;let known=new Set(<?= json_encode($latestIds) ?>),soundOn=false,audioCtx=null,firstPoll=true;const soundToggle=document.getElementById('soundToggle');soundToggle.addEventListener('click',async()=>{try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();soundOn=true;soundToggle.textContent='Suara pesanan aktif ✓';}catch(e){alert('browser tidak mendukung suara otomatis.')}});function beep(){if(!soundOn||!audioCtx)return;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);osc.frequency.value=880;gain.gain.value=.08;osc.start();osc.stop(audioCtx.currentTime+.18)}async function poll(){try{const r=await fetch(API+'?action=list',{cache:'no-store'}),d=await r.json();if(!d.ok)return;let count=0;for(const o of d.orders){if(!firstPoll&&!known.has(Number(o.id))&&new Date(o.created_at).toDateString()===new Date().toDateString()){count++;known.add(Number(o.id))}}firstPoll=false;document.getElementById('openCount').textContent=d.orders.filter(o=>['Diterima','Diproses','Siap'].includes(o.status_pesanan)&&new Date(o.created_at).toDateString()===new Date().toDateString()).length;if(count){beep();const n=document.getElementById('alertNote');n.textContent=count+' pesanan baru masuk!';n.classList.remove('hidden');setTimeout(()=>n.classList.add('hidden'),6000)}}catch(e){}}
setInterval(poll,5000);document.querySelectorAll('[data-stock-toggle]').forEach(b=>b.addEventListener('click',async()=>{const f=new FormData();f.append('_csrf',b.dataset.csrf);f.append('action','availability');f.append('id',b.dataset.stockToggle);try{const r=await fetch(API,{method:'POST',body:f}),d=await r.json();if(d.ok)location.reload();else alert(d.message)}catch(e){alert('koneksi gagal')}}));
</script><?php require __DIR__.'/../includes/admin-footer.php'; ?>
